// Box 하나마다 별도의 재고 필드가 있어요.
class Box {
    int count;
    Box(int initial) {
        count = initial;
    }
}

class Main {

    public static void main(String[] args) {
        // 새 상자를 만들고 그 필드를 읽어요.
        Box a = new Box(2);
        System.out.println(a.count);
    }
}

// Box 하나마다 별도의 재고 필드가 있어요.
class Box {
    int count;
    Box(int initial) {
        count = initial;
    }
}

class Main {

    public static void main(String[] args) {
        // new를 두 번 써서 상자를 따로 만들어요.
        Box a = new Box(2);
