// Box 하나마다 별도의 재고 필드가 있어요.
class Box {
    int count;
    Box(int initial) {
        count = initial;
    }
}

class Main {

    public static void main(String[] args) {
        // 참조를 복사해 같은 상자를 가리켜요.
        Box a = new Box(2);
        Box b = a;
        // b로 고친 뒤 a와 b로 읽어요.
        b.count = 7;
        System.out.println(a.count);
        System.out.println(b.count);
        System.out.println(a == b);
    }
}

// Box 하나마다 별도의 재고 필드가 있어요.
class Box {
    int count;
    Box(int initial) {
        count = initial;
    }
