// Box 하나마다 별도의 재고 필드가 있어요.
class Box {
    int count;
    Box(int initial) {
        count = initial;
    }
}

class Main {
    // 전달받은 참조로 같은 객체의 필드를 바꿔요.
    static void add(Box item) {
        item.count = item.count + 1;
    }

    public static void main(String[] args) {
        // 참조 값이 매개변수로 복사돼요.
        Box a = new Box(2);
        add(a);
        System.out.println(a.count);
    }
}

