    Box(int initial) {
        count = initial;
    }
}

class Main {

    public static void main(String[] args) {
        // 이 Box는 equals를 새로 정의하지 않았어요.
        Box a = new Box(2);
        Box b = new Box(2);
        System.out.println(a == b);
        System.out.println(a.equals(b));
    }
}

class Main {

